<include file="Public:header"/>	<div class="mainbox">		<table class="search_table" width="100%">			<tr>				<td style="width:60%;">					总佣金列表				</td>			</tr>		</table>					<div class="table-list">				<table width="100%" cellspacing="0">					<colgroup><col> <col><col width="240" align="center"> </colgroup>					<thead>						<tr>							<th>金额</th>							<th>描述</th>							<th>时间</th>						</tr>					</thead>					<tbody>						<if condition="is_array($list)">							<volist name="list" id="vo">								<tr>									<td>{pigcms{$vo.money}</td>									<td>{pigcms{$vo.des}</td>									<td>{pigcms{$vo.add_time|date='Y-m-d H:i:s',###}</td>								</tr>							</volist>							<tr><td class="textcenter pagebar" colspan="5">{pigcms{$pagebar}</td></tr>						<else/>							<tr><td class="textcenter red" colspan="5">列表为空！</td></tr>						</if>					</tbody>				</table>			</div>	</div><include file="Public:footer"/>